@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --navy: #0A1628;
  --navy-light: #152C4F;
  --gold: #C5A059;
  --gold-hover: #D8B266;
  --teal: #012A2D;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-400: #9CA3AF;
  --gray-600: #4B5563;
  --gray-800: #1F2937;

  --font-sans: 'Inter', sans-serif;
  --transition: all 0.3s ease;

  --container-px: 24px;
}

@media (min-width: 768px) {
  :root { --container-px: 40px; }
}
@media (min-width: 1024px) {
  :root { --container-px: 64px; }
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: var(--font-sans); color: var(--gray-800); line-height: 1.6; background: var(--white); -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration: none; transition: var(--transition); }
img { max-width: 100%; height: auto; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; transition: var(--transition); }

/* Typography */
h1, h2, h3, h4, h5 { color: var(--navy); font-weight: 600; line-height: 1.2; }
h1 { font-size: 2.5rem; letter-spacing: -0.02em; }
h2 { font-size: 2rem; letter-spacing: -0.01em; margin-bottom: 1rem; }
h3 { font-size: 1.5rem; margin-bottom: 0.75rem; }
p { margin-bottom: 1rem; color: var(--gray-600); }
.text-gold { color: var(--gold); }
.text-white { color: var(--white); }
.text-white p { color: var(--gray-200); }
.text-center { text-align: center; }

@media (min-width: 768px) {
  h1 { font-size: 3.5rem; }
  h2 { font-size: 2.5rem; }
}

/* Layout */
.container { max-width: 1280px; margin: 0 auto; padding: 0 var(--container-px); }
.section { padding: 5rem 0; }
.section-dark { background-color: var(--navy); color: var(--white); }
.section-dark h1, .section-dark h2, .section-dark h3 { color: var(--white); }
.section-gray { background-color: var(--gray-50); }
.grid { display: grid; gap: 2rem; }
.grid-2 { grid-template-columns: 1fr; }
.grid-3 { grid-template-columns: 1fr; }
.grid-4 { grid-template-columns: 1fr; }
@media (min-width: 768px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
}

/* Buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; padding: 0.75rem 1.5rem; font-weight: 500; font-size: 1rem; border-radius: 2px; }
.btn-primary { background-color: var(--gold); color: var(--white); }
.btn-primary:hover { background-color: var(--gold-hover); }
.btn-outline { border: 1px solid var(--gray-200); color: var(--navy); }
.btn-outline:hover { border-color: var(--navy); background-color: var(--navy); color: var(--white); }
.btn-outline-white { border: 1px solid rgba(255,255,255,0.3); color: var(--white); }
.btn-outline-white:hover { border-color: var(--white); background-color: var(--white); color: var(--navy); }
.btn-link { color: var(--gold); font-weight: 500; display: inline-flex; align-items: center; gap: 0.5rem; }
.btn-link::after { content: '→'; transition: transform 0.2s; }
.btn-link:hover::after { transform: translateX(4px); }

/* Header & Nav */
.header { position: sticky; top: 0; z-index: 100; background: var(--white); border-bottom: 1px solid var(--gray-200); }
.nav-container { display: flex; justify-content: space-between; align-items: center; height: 80px; }
.logo { font-size: 1.5rem; font-weight: 700; color: var(--navy); display: flex; align-items: center; gap: 0.5rem; letter-spacing: -0.02em; }
.logo span { color: var(--gold); }
.nav-links { display: none; height: 100%; }
.nav-link { height: 100%; display: flex; align-items: center; padding: 0 1rem; color: var(--gray-800); font-weight: 500; font-size: 0.95rem; border-bottom: 2px solid transparent; }
.nav-link:hover, .nav-item.active .nav-link { color: var(--navy); border-bottom-color: var(--gold); }
.nav-item { position: relative; height: 100%; }
.mobile-menu-btn { display: block; font-size: 1.5rem; background: none; border: none; color: var(--navy); }
@media (min-width: 1024px) {
  .nav-links { display: flex; }
  .mobile-menu-btn { display: none; }
}

/* Mega Menu */
.mega-menu { position: absolute; top: 100%; left: 50%; transform: translateX(-50%); width: 100vw; background: var(--white); border-top: 1px solid var(--gray-200); box-shadow: 0 10px 25px rgba(0,0,0,0.05); padding: 3rem 0; opacity: 0; visibility: hidden; transition: var(--transition); z-index: 101; pointer-events: none; display: flex; justify-content: center; }
.nav-item:hover .mega-menu { opacity: 1; visibility: visible; pointer-events: auto; }
.mega-menu-inner { width: 100%; max-width: 1280px; padding: 0 var(--container-px); display: grid; grid-template-columns: 2fr 1fr; gap: 4rem; }
.mega-menu-col h4 { font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-400); margin-bottom: 1.5rem; border-bottom: 1px solid var(--gray-200); padding-bottom: 0.5rem; }
.mega-menu-list { list-style: none; display: grid; gap: 1rem; }
.mega-menu-list a { display: block; color: var(--gray-800); font-weight: 500; font-size: 1rem; }
.mega-menu-list a:hover { color: var(--gold); transform: translateX(4px); }
.mega-menu-list-2col { grid-template-columns: repeat(2, 1fr); }

/* Mobile Menu */
.mobile-nav { position: fixed; inset: 0; top: 80px; background: var(--white); z-index: 99; padding: 2rem var(--container-px); overflow-y: auto; display: none; }
.mobile-nav.active { display: block; }
.mobile-nav-item { border-bottom: 1px solid var(--gray-200); }
.mobile-nav-link { display: flex; justify-content: space-between; align-items: center; width: 100%; padding: 1.25rem 0; font-size: 1.125rem; font-weight: 500; color: var(--navy); text-align: left; }
.mobile-nav-sub { display: none; padding-bottom: 1.25rem; }
.mobile-nav-sub.active { display: block; }
.mobile-nav-sub a { display: block; padding: 0.75rem 0; color: var(--gray-600); }

/* Hero Sections */
.hero { position: relative; padding: 8rem 0; min-height: 80vh; display: flex; align-items: center; background-color: var(--navy); overflow: hidden; }
.hero::before { content: ''; position: absolute; inset: 0; background: linear-gradient(to right, rgba(10,22,40,0.9) 0%, rgba(10,22,40,0.4) 100%); z-index: 1; }
.hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0.5; }
.hero-content { position: relative; z-index: 2; max-width: 800px; color: var(--white); }
.hero-content h1 { margin-bottom: 1.5rem; }
.hero-content p { font-size: 1.25rem; margin-bottom: 2.5rem; color: var(--gray-200); max-width: 600px; }
.hero-small { min-height: 50vh; padding: 6rem 0; }

/* Cards & Grid Items */
.card { background: var(--white); border: 1px solid var(--gray-200); transition: var(--transition); height: 100%; display: flex; flex-direction: column; overflow: hidden; }
.card:hover { box-shadow: 0 10px 30px rgba(0,0,0,0.08); transform: translateY(-4px); border-color: var(--gold); }
.card-img-wrap { position: relative; padding-top: 56.25%; overflow: hidden; background: var(--gray-100); }
.card-img { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.card:hover .card-img { transform: scale(1.05); }
.card-content { padding: 2rem; flex: 1; display: flex; flex-direction: column; }
.card-meta { font-size: 0.875rem; color: var(--gold); font-weight: 600; text-transform: uppercase; margin-bottom: 0.5rem; letter-spacing: 0.05em; }
.card-title { font-size: 1.25rem; margin-bottom: 1rem; color: var(--navy); }
.card-desc { color: var(--gray-600); flex: 1; margin-bottom: 1.5rem; }

/* Announcement Banner */
.banner { background: var(--teal); color: var(--white); padding: 1rem 0; text-align: center; font-size: 0.95rem; font-weight: 500; display: flex; align-items: center; justify-content: center; gap: 1rem; flex-wrap: wrap; }
.banner a { color: var(--gold); text-decoration: underline; }

/* Tabs - What We Do */
.tabs-section { display: grid; gap: 2rem; }
@media (min-width: 1024px) { .tabs-section { grid-template-columns: 1fr 2fr; gap: 4rem; } }
.tabs-list { display: flex; flex-direction: column; gap: 0.5rem; }
.tab-btn { padding: 1.5rem; text-align: left; font-size: 1.25rem; font-weight: 600; color: var(--gray-400); border-left: 4px solid var(--gray-200); background: transparent; transition: var(--transition); display: flex; justify-content: space-between; align-items: center;}
.tab-btn::after { content: '→'; opacity: 0; transition: var(--transition); transform: translateX(-10px); }
.tab-btn:hover { color: var(--navy); background: var(--gray-50); }
.tab-btn.active { color: var(--navy); border-left-color: var(--gold); background: var(--white); box-shadow: 0 4px 20px rgba(0,0,0,0.05); }
.tab-btn.active::after { opacity: 1; transform: translateX(0); color: var(--gold); }
.tab-content { display: none; animation: fadeIn 0.5s ease; padding: 3rem; background: var(--white); box-shadow: 0 4px 20px rgba(0,0,0,0.05); border-left: 2px solid var(--gold); }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

/* Capabilities Grid */
.cap-grid { display: grid; gap: 2rem; }
@media (min-width: 768px) { .cap-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .cap-grid { grid-template-columns: repeat(3, 1fr); } }
.cap-item { padding: 2.5rem; background: var(--gray-50); border-top: 3px solid var(--navy); transition: var(--transition); height: 100%; display: flex; flex-direction: column; }
.cap-item:hover { background: var(--white); box-shadow: 0 10px 30px rgba(0,0,0,0.08); border-top-color: var(--gold); transform: translateY(-4px); }
.cap-icon { width: 48px; height: 48px; display: flex; align-items: center; justify-content: center; background: rgba(197, 160, 89, 0.1); color: var(--gold); border-radius: 4px; margin-bottom: 1.5rem; }
.cap-icon svg { width: 24px; height: 24px; }

/* Newsletter */
.newsletter-form { display: flex; gap: 1rem; max-width: 500px; margin-top: 1.5rem; flex-wrap: wrap; }
.newsletter-input { flex: 1; min-width: 200px; padding: 1rem 1.5rem; border: 1px solid rgba(255,255,255,0.2); background: rgba(255,255,255,0.05); color: var(--white); border-radius: 2px; outline: none; transition: var(--transition); }
.newsletter-input::placeholder { color: rgba(255,255,255,0.5); }
.newsletter-input:focus { background: rgba(255,255,255,0.1); border-color: var(--gold); }

/* Footer */
.footer { background: var(--navy-light); color: var(--gray-200); padding: 5rem 0 2rem; font-size: 0.9rem; }
.footer-grid { display: grid; gap: 3rem; margin-bottom: 4rem; }
@media (min-width: 768px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .footer-grid { grid-template-columns: 2fr 1fr 1fr 1fr; } }
.footer-logo { font-size: 1.5rem; font-weight: 700; color: var(--white); margin-bottom: 1rem; display: block; }
.footer-logo span { color: var(--gold); }
.footer h4 { color: var(--white); font-size: 1rem; margin-bottom: 1.5rem; }
.footer ul { list-style: none; display: grid; gap: 0.75rem; }
.footer a:hover { color: var(--gold); }
.footer-bottom { padding-top: 2rem; border-top: 1px solid rgba(255,255,255,0.1); display: flex; flex-direction: column; gap: 1rem; align-items: center; text-align: center; }
@media (min-width: 768px) { .footer-bottom { flex-direction: row; justify-content: space-between; text-align: left; } }
.footer-legal { display: flex; gap: 1.5rem; flex-wrap: wrap; justify-content: center; }

/* Utilities */
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-6 { margin-bottom: 1.5rem; }
.mb-8 { margin-bottom: 2rem; }
.mb-12 { margin-bottom: 3rem; }
.mt-4 { margin-top: 1rem; }
.mt-8 { margin-top: 2rem; }
.mt-12 { margin-top: 3rem; }
.flex { display: flex; }
.items-center { align-items: center; }
.gap-2 { gap: 0.5rem; }
.gap-4 { gap: 1rem; }
.justify-between { justify-content: space-between; }

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const mobileMenuBtn = document.getElementById('mobile-menu-btn');
  const mobileNav = document.getElementById('mobile-nav');

  if (mobileMenuBtn && mobileNav) {
    mobileMenuBtn.addEventListener('click', () => {
      mobileNav.classList.toggle('active');
    });
  }

  // Mobile Accordion
  const mobileNavLinks = document.querySelectorAll('.mobile-nav-link');
  mobileNavLinks.forEach(link => {
    link.addEventListener('click', (e) => {
      const subMenu = link.nextElementSibling;
      if (subMenu && subMenu.classList.contains('mobile-nav-sub')) {
        e.preventDefault();
        subMenu.classList.toggle('active');
        const icon = link.querySelector('svg');
        if (icon) {
          icon.style.transform = subMenu.classList.contains('active') ? 'rotate(180deg)' : 'rotate(0)';
        }
      }
    });
  });

  // What We Do Tabs
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');

  if (tabBtns.length > 0 && tabContents.length > 0) {
    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const targetId = btn.getAttribute('data-tab');

        // Remove active class from all buttons and contents
        tabBtns.forEach(b => b.classList.remove('active'));
        tabContents.forEach(c => c.classList.remove('active'));

        // Add active class to clicked button and target content
        btn.classList.add('active');
        const targetContent = document.getElementById(targetId);
        if (targetContent) targetContent.classList.add('active');
      });
    });
  }

  // Newsletter Subscribe
  const subscribeBtn = document.getElementById('subscribe-btn');
  if (subscribeBtn) {
    subscribeBtn.addEventListener('click', (e) => {
      e.preventDefault();
      alert('Thank you for subscribing to Our Take Newsletter!');
    });
  }

  // Invest Carousel
  const prevBtn = document.getElementById('carousel-prev');
  const nextBtn = document.getElementById('carousel-next');
  const carouselTrack = document.getElementById('carousel-track');

  if (prevBtn && nextBtn && carouselTrack) {
    let scrollPos = 0;
    nextBtn.addEventListener('click', () => {
      const itemWidth = carouselTrack.children[0].offsetWidth + 32; // Include gap
      scrollPos += itemWidth;
      if (scrollPos >= carouselTrack.scrollWidth - carouselTrack.clientWidth) {
        scrollPos = carouselTrack.scrollWidth - carouselTrack.clientWidth;
      }
      carouselTrack.scrollTo({ left: scrollPos, behavior: 'smooth' });
    });

    prevBtn.addEventListener('click', () => {
      const itemWidth = carouselTrack.children[0].offsetWidth + 32; // Include gap
      scrollPos -= itemWidth;
      if (scrollPos < 0) scrollPos = 0;
      carouselTrack.scrollTo({ left: scrollPos, behavior: 'smooth' });
    });
  }
});
